import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const out = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(out, '../../..');
const docs = Object.fromEntries(JSON.parse(fs.readFileSync(path.join(root, 'data/extracted/inventory.json'), 'utf8')).map(e => [e.articleId.slice(8), JSON.parse(fs.readFileSync(path.join(root, 'data/extracted', e.outputFile), 'utf8'))]));
const primary = '94e7a19d8878';
function q(id, page, start, end) {
  const text = docs[id].pages.find(x => x.page === page).text;
  const from = text.indexOf(start), to = text.indexOf(end, from);
  if (from < 0 || to < from) throw Error(`Missing quote ${id} p${page}: ${start} ... ${end}`);
  return { id, page, text: text.slice(from, to + end.length) };
}
function range(page, start, next) {
  const text = docs[primary].pages[page - 1].text;
  const from = text.indexOf(start), to = next ? text.indexOf(next, from + start.length) : text.length;
  if (from < 0 || to < from) throw Error(`Missing Art48 range ${page}: ${start}`);
  return {id: primary, page, text: text.slice(from, to).trim()};
}
