const cards = [];
const source = (id, pieces, sections) => ({file: docs[id].file, title: docs[id].title, pages: [...new Set(pieces.map(x=>x.page))], sections, evidence: pieces.map(x=>x.text)});
function add(question, answer, sections, pieces, other = [], otherSections = []) {
  const id = `${docs[primary].articleId}-${String(cards.length + 9).padStart(2,'0')}`;
  const card = {id, articleId: docs[primary].articleId, question, answer, source: source(primary,pieces,sections), kind: other.length ? 'synthesis' : 'direct'};
  if(other.length) card.relatedSources = [...new Set(other.map(x=>x.id))].map(k=>({articleId:docs[k].articleId,source:source(k,other.filter(x=>x.id===k),otherSections)}));
  cards.push(card);
}

// 25 direct questions: more granular than the eight preserved overview cards.
add('No texto local do Art. 48, por que olhar apenas para redes de vídeos deixaria de fora parte do escopo dos incisos I e II?',
'O inciso I inclui provedores de aplicações de internet com funcionalidades de [[hospedagem de conteúdos audiovisuais gerados por terceiros]], inclusive vídeos e transmissões ao vivo. O inciso II também abrange [[mensageria eletrônica e outros serviços digitais]] que permitem enviar, receber e compartilhar mensagens entre usuários, em ambiente público ou privado. Portanto, o recorte apresentado alcança tanto serviços de conteúdo audiovisual quanto comunicação entre pessoas; não fica restrito a feeds públicos de vídeos.', ['Art. 48, incisos I e II'],[a.scope]);
add('O §2º do documento permite deduzir, sozinho, quais eixos do art. 12 e quais faixas etárias se aplicam a cada funcionalidade?',
'Não. O §2º determina que a atribuição se baseie nos [[Guias Práticos de Classificação Indicativa]], observando os eixos temáticos previstos no art. 12. O arquivo fornecido não reproduz aqui esses eixos nem uma tabela de correspondência entre funcionalidades e idades. A resposta fundamentada identifica a [[remissão a critérios externos ao trecho]], sem inventar seus conteúdos nem transformar uma funcionalidade listada em faixa etária automática.', ['Art. 48, §2º'],[a.guide]);
add('Quais grupos de produtos e serviços destinados a adultos são exemplificados no §8º, e a enumeração se apresenta como fechada?',
'O §8º enumera, [[entre outros]], bebidas alcoólicas; cigarros e derivados do tabaco; produtos cujos componentes possam causar dependência física ou psíquica, ainda que por uso indevido; sites de apostas; serviços de acompanhantes; sites pornográficos; compra e venda de armas, munições e explosivos; e qualquer produto ou serviço destinado a adultos segundo a legislação brasileira. Trata-se, no documento, de uma [[lista exemplificativa]] para o tratamento da publicidade do §7º, não de uma taxonomia exaustiva de todos os riscos digitais.', ['Art. 48, §§7º e 8º'],[a.ad,a.adlist1,a.adlist2]);
add('Como o §9º amplia a observação da publicidade para além da peça que aparece diretamente na tela?',
'O §9º estende o disposto nos §§7º e 8º aos [[enlaces, hiperlinks e redirecionamentos]] oferecidos nos aplicativos quando patrocinados ou impulsionados. Assim, segundo o texto local, a consideração classificatória alcança a publicidade que conduz à apresentação ou ao acesso a conteúdos impróprios ou destinados a adultos, mesmo quando esse destino está além da tela inicial. A condição [[patrocinado ou impulsionado]] deve ser mantida; o trecho não afirma o mesmo, indistintamente, sobre todo link existente.', ['Art. 48, §§7º a 9º'],[a.ad,a.links]);
add('No §10º, inciso I, quais dimensões de conteúdo entram na avaliação além de uma oposição simples entre sexual e não sexual?',
'O inciso I menciona conteúdos de natureza [[sexual, violenta ou discriminatória]], além daqueles que atentem contra a [[dignidade humana]]. Eles aparecem no conjunto de conteúdos, funcionalidades ou ferramentas que os fornecedores ofertem ou promovam direta ou indiretamente. A leitura deve preservar esse alcance e não reduzir o dispositivo local à presença de nudez nem inferir uma idade específica que o trecho não fornece.', ['Art. 48, §10º, caput e inciso I'],[a.features]);
add('Que diferença há entre representar violência e oferecer desafios ou interações que estimulem comportamentos de risco, no §10º apresentado?',
'O inciso I se refere à natureza de conteúdos, incluindo os violentos. O inciso II explicita outro foco: [[desafios, jogos ou interações que estimulem comportamentos de risco, autolesão ou violência]]. A avaliação descrita não se limita ao que uma imagem representa: também inclui o que uma atividade propõe ou estimula. Isso é uma distinção textual entre conteúdos e dinâmicas de interação; não constitui uma comprovação causal de dano de um produto concreto.', ['Art. 48, §10º, incisos I e II'],[a.features]);
add('Como o inciso III do §10º caracteriza os mecanismos de interação relevantes para a classificação, sem depender de uma lista de nomes de recursos?',
'O inciso III considera mecanismos de interação que incentivem [[compulsividade, dependência ou exposição prolongada a conteúdos inadequados]]. O critério apresentado descreve uma relação funcional entre interação e incentivo, enquanto outros incisos trazem exemplos de funcionalidades. A leitura não deve substituir essa formulação por um diagnóstico clínico dos usuários nem afirmar que o simples uso de uma técnica demonstra dependência em um caso particular.', ['Art. 48, §10º, inciso III'],[a.features]);
add('Por que o inciso IV do §10º considera tanto facilitar quanto induzir o acesso a ambientes adultos?',
'O texto inclui [[acesso facilitado ou induzido]] a ambientes, páginas ou perfis destinados exclusivamente a maiores de idade. Ele alcança, portanto, tanto a facilidade de chegar a esses espaços quanto mecanismos que direcionem o usuário até eles, sem se restringir a conteúdos hospedados na própria interface inicial. A condição de serem espaços [[exclusivos para adultos]] integra o trecho e não deve ser apagada da explicação.', ['Art. 48, §10º, inciso IV'],[a.features]);
add('Qual papel o inciso V do §10º exerce em relação à extensa lista de funcionalidades do documento?',
'O inciso V inclui qualquer outro conteúdo ou funcionalidade que, [[nos termos dos Guias Práticos de Classificação Indicativa]], se enquadre como impróprio para determinadas faixas etárias. Ele evita tratar a lista do §10º como inventário fechado, mas não dá liberdade para inventar critérios: a abertura permanece vinculada aos Guias. O documento não fornece, nesse inciso, o conteúdo integral desses critérios nem uma faixa etária aplicável a cada exemplo.', ['Art. 48, §10º, inciso V'],[a.features]);
add('Como a comunicação direta entre usuários conecta o escopo da mensageria ao inventário de funcionalidades do Art. 48 local?',
'O inciso II do caput inclui serviços que permitem envio, recebimento e compartilhamento de mensagens em ambiente público ou privado. O §10º, inciso VI, acrescenta [[interações ou comunicações diretas on-line entre usuários]] entre as funcionalidades consideradas. A conexão mostra que a comunicação não é apenas um tipo de serviço abrangido: também é uma característica de interação observada na avaliação. O texto não restringe essa característica a feeds públicos.', ['Art. 48, inciso II; §10º, inciso VI'],[a.scope,a.features]);
add('Que especificidade o compartilhamento de localização tem no inventário do §10º, e por que não convém apagá-la sob o rótulo genérico de dados?',
'O inciso VII menciona separadamente o [[compartilhamento da localização do usuário]]. O mesmo parágrafo também cita, no inciso X, compartilhamento ou fornecimento de dados pessoais e, no XI, desativação de mecanismos de privacidade. São aspectos próximos, mas textualmente distintos: localização é uma funcionalidade específica, circulação de dados é outra dimensão e remoção de uma proteção é uma terceira. O arquivo não informa pesos ou idades para cada uma.', ['Art. 48, §10º, incisos VII, X e XI'],[a.features]);
add('Que aspecto de fotos e vídeos o inciso VIII do §10º acrescenta à análise, além de sua simples presença na plataforma?',
'O inciso VIII considera [[ferramentas que permitem alterar a aparência de fotos ou vídeos]]. Isso desloca a atenção do conteúdo audiovisual apenas como objeto exibido para as possibilidades de transformação que a interface oferece. No mesmo inventário, compartilhamento de mídia e realização de filmagens ou fotografias aparecem em incisos próprios. O documento permite distinguir essas funcionalidades; não descreve um efeito psicológico específico de todo editor de aparência.', ['Art. 48, §10º, incisos VIII, XII e XIV'],[a.features,a.features2]);
add('O inciso IX do §10º exige que uma compra tenha sido efetivamente concluída para que compras on-line sejam consideradas?',
'A formulação citada é a [[possibilidade de realização de compras on-line]]. Ela descreve uma capacidade disponibilizada pelo serviço, e não exige, nesse trecho, comprovar que um usuário realizou uma transação. Essa distinção é importante para observar o desenho de uma interface antes de uma compra efetiva. O texto não apresenta aqui regras sobre preços, contratos de compra ou idades específicas.', ['Art. 48, §10º, inciso IX'],[a.features]);
add('Como diferenciar permissão de fornecer dados e desativação de proteções de privacidade nos incisos X e XI do §10º?',
'O inciso X trata da [[permissão de compartilhamento ou fornecimento de dados pessoais]]. O inciso XI trata da [[desativação de mecanismos que protegem a privacidade]]. O primeiro aponta para a possibilidade de circulação de informação; o segundo para a retirada de uma barreira de proteção. Uma avaliação que registrasse apenas se o aplicativo pede dados perderia essa segunda dimensão. O documento não afirma que ambos os recursos tenham o mesmo peso classificatório.', ['Art. 48, §10º, incisos X e XI'],[a.features]);
add('Quais três dimensões de produção e circulação audiovisual podem ser distinguidas entre os incisos XII, XIV e XV?',
'O inciso XII cita [[compartilhamento de mídia]]; o XIV, [[realização ou inclusão de filmagens ou fotografias]]; e o XV, [[transmissões ao vivo]]. Compartilhar, produzir/incluir registros e transmitir em tempo real são possibilidades diferenciadas no inventário apresentado. A distinção permite descrever uma plataforma com mais precisão do que afirmar apenas que ela contém imagens, preservando a necessidade de aplicar os critérios indicados no próprio documento.', ['Art. 48, §10º, incisos XII, XIV e XV'],[a.features,a.features2]);
add('Como o documento distingue conteúdo sobre uso de drogas de publicidade relacionada a produtos que podem causar dependência?',
'No §10º, inciso XIII, aparece a [[apresentação de conteúdos relacionados ao uso de drogas]]. Já o §8º, inciso III, inclui produtos cujos componentes possam causar [[dependência física ou psíquica]], ainda que por utilização indevida, na lista relacionada à publicidade do §7º. Um trecho trata de conteúdo apresentado; o outro, de uma categoria de produto no encadeamento publicitário. A proximidade temática não autoriza apagar essa diferença de contexto.', ['Art. 48, §8º, inciso III; §10º, inciso XIII'],[a.ad,a.adlist2,a.features2]);
add('Como a funcionalidade de apostas do inciso XVI difere da mera presença de publicidade para um site de apostas no §8º?',
'O §8º inclui sites de jogos de apostas entre destinos relevantes para o tratamento da publicidade. O §10º, inciso XVI, considera [[funcionalidades que apresentem probabilidades relacionadas a jogos ou atividades do mundo real e que possibilitem, estimulem ou incentivem apostas]]. Nesse segundo caso, a atenção está na funcionalidade e em sua relação com apostar, não apenas no anúncio de um destino externo. O trecho não diz que toda exibição de probabilidade, isoladamente, é equivalente a essa condição.', ['Art. 48, §8º, inciso IV; §10º, inciso XVI'],[a.adlist2,a.features2]);
add('Que possibilidade de passagem da interação digital para encontros entre pessoas aparece no inciso XVII?',
'O inciso XVII inclui [[funcionalidades que promovam ou facilitem a consumação de encontros entre pessoas]]. O objeto considerado é a possibilidade funcional de promover ou facilitar esses encontros. Isso não deve ser reduzido a uma categoria comercial de aplicativo nem convertido em uma alegação de que todo encontro é danoso: o documento apenas o inclui entre os elementos observados para classificação.', ['Art. 48, §10º, inciso XVII'],[a.features2]);
add('Por que curadoria personalizada e impulsionamento devem ser registrados separadamente ao ler os incisos XVIII e XIX?',
'O inciso XVIII cita [[curadoria automatizada, personalização e recomendação de conteúdo]]. O XIX menciona [[impulsionamento de conteúdo e sites sugeridos pelo próprio aplicativo]]. A lista diferencia a seleção/adaptação do que é mostrado e mecanismos de ampliação ou sugestão de destinos. As dimensões podem se combinar numa interface, mas a análise textual deve nomeá-las sem presumir que são uma única técnica ou que todo uso delas tem um efeito psicológico já demonstrado.', ['Art. 48, §10º, incisos XVIII e XIX'],[a.features2]);
add('Como o inciso XXII faz a participação de crianças e adolescentes atravessar as funcionalidades anteriores?',
'O inciso XXII considera a [[possibilidade de participação de crianças e adolescentes em qualquer uma das interações descritas nos incisos anteriores]]. Não é apresentado como um recurso isolado adicional: ele pede atenção à participação desse público no conjunto das interações já enumeradas. Na análise do documento, isso permite correlacionar idade e funcionalidades sem inventar uma idade de corte que não aparece no trecho.', ['Art. 48, §10º, inciso XXII'],[a.features2]);
add('O que se observa no prestador, e não apenas no conteúdo individual, quando o §14, inciso I, fala em controle editorial e curadoria?',
'O §14 inclui, para a classificação final, o [[grau de controle editorial e de curadoria exercido pelo prestador]] sobre os conteúdos disponibilizados. O foco é também a atuação e a capacidade de seleção do serviço, e não somente a identificação de um item de conteúdo. O texto cita esse grau como elemento a considerar, sem fornecer uma escala operacional completa; o §15 remete o detalhamento técnico aos Guias.', ['Art. 48, §14, inciso I; §15'],[a.editorial,a.details]);
add('Como o §14 qualifica os controles parentais, e o que o trecho deixa em aberto sobre sua implementação?',
'O inciso II exige considerar a existência de [[ferramentas de controle etário e controles parentais acessíveis ao usuário]]. A acessibilidade integra expressamente a descrição, de modo que apenas mencionar a existência nominal de uma ferramenta não reproduz todo o texto. O trecho não detalha desenho de interface, modo de autenticação ou eficácia das ferramentas; pelo §15, especificações técnicas e operacionais serão detalhadas nos Guias.', ['Art. 48, §14, inciso II; §15'],[a.moderation,a.details]);
add('Quais alternativas de moderação de conteúdos sensíveis o §14, inciso III, contempla, e qual qualificação acompanha essas políticas?',
'O inciso III considera políticas de moderação que [[restrinjam o acesso de menores a conteúdos sensíveis ou proíbam tais conteúdos na aplicação]]. A formulação apresenta duas alternativas e as qualifica pelo alinhamento ao [[Marco Civil da Internet, Lei nº 12.965, de 23 de abril de 2014]], conforme o documento local. Ela não permite concluir que qualquer bloqueio ou proibição, independentemente de sua política e contexto, satisfaça automaticamente os critérios mencionados.', ['Art. 48, §14, inciso III'],[a.moderation]);
add('Que limite à aplicação imediata de um checklist o §15 estabelece para os critérios do §14?',
'O §15 remete as [[especificações técnicas e operacionais]] dos critérios do §14 e seus incisos aos [[Guias Práticos de Classificação Indicativa]]. O arquivo enumera os aspectos de curadoria, controle etário/parental e moderação, mas não reproduz aqui todo o procedimento de aplicação. Por isso, a descrição fundamentada separa inventário de aspectos e detalhamento operacional, sem preencher esse último com conhecimento externo ou supor uma pontuação inexistente no texto.', ['Art. 48, §§14 e 15'],[a.editorial,a.moderation,a.details]);
add('O §13 do documento local vincula a divulgação de representantes a quais finalidades institucionais?',
'O §13 trata dos provedores de aplicações de internet que operem no território nacional e determina disponibilizar, de forma [[clara e atualizada]], informações relativas aos seus representantes. As finalidades explicitadas são [[comunicação institucional, comunicação regulatória e responsabilização]], nos termos da legislação mencionada pelo próprio trecho. Trata-se de uma dimensão de identificação e interlocução do prestador; não é uma demonstração de que fiscalização ou responsabilização tenham ocorrido num caso concreto.', ['Art. 48, §13'],[a.representative]);

// 25 cross-source questions, each a supported analytical comparison.
add('Como o §14 do Art. 48 local e o princípio de responsabilidade do prestador em Safety by Design deslocam a atenção do usuário isolado para o serviço?',
'No Art. 48 local, a classificação final também considera [[controle editorial, controles etários/parentais acessíveis e políticas de moderação]]. Safety by Design, no Princípio 1, sustenta que a responsabilidade é compartilhada, mas que o [[ônus da segurança nunca deve recair somente sobre o usuário final]], e que danos conhecidos e antecipados devem ser avaliados no projeto e na oferta do serviço. A correlação é uma leitura comparativa: ambos permitem examinar o que o prestador faz, além das escolhas individuais. Eles têm escopos diferentes — critérios de classificação de um documento local e orientação preventiva voluntária — e não demonstram, por sua simples presença, que uma plataforma é segura.', ['Art. 48, §14'],[a.editorial,a.moderation],[s.prevention,s.voluntary],['Principle 1: Service provider responsibilities','V. Safety by Design Principles']);
add('Por que a existência de controles parentais no Art. 48 não equivale, por si só, à orientação de configurações seguras por padrão em Safety by Design?',
'O §14, inciso II, considera a [[existência de controles etários e parentais acessíveis]]. O Princípio 2.1 de Safety by Design acrescenta outra especificidade de projeto: ferramentas de gestão da segurança com [[privacidade e segurança no nível mais protetivo por padrão]], desde o registro, e oportunidades de rever preferências. A comparação distingue disponibilidade e acessibilidade de uma ferramenta de sua configuração inicial e do controle que ela proporciona. São dimensões complementares para examinar uma interface, sem afirmar que o documento local prescreve literalmente todos os detalhes do Princípio 2.1.', ['Art. 48, §14, inciso II'],[a.moderation],[s.defaults],['Principle 2.1']);
add('Como a exibição de informação etária do Art. 48 pode ser relacionada à transparência das políticas em Safety by Design sem confundir suas exigências?',
'Os §§5º e 6º do documento local tratam de [[indicações etárias e descritores claros e acessíveis]] no acesso, instalação, login e início de uso. O Princípio 3.2 de Safety by Design recomenda políticas visíveis, fáceis de encontrar, atualizadas e compreensíveis, com lembranças periódicas e comunicação de mudanças. A conexão é que disponibilizar informação envolve [[localização, compreensão e oportunidade de acesso]]. O objeto informacional é diferente: a comparação não transforma informação etária em toda a política de segurança nem prova que os usuários a compreenderam.', ['Art. 48, §§5º e 6º'],[a.display],[s.transparent],['Principle 3.2']);
add('Qual tensão surge ao aproximar a exclusão de bloqueio por faixa etária de conteúdos de usuários no §3º e os alertas/age-gates descritos em Safety by Design?',
'O §3º do Art. 48 local diz que conteúdos de usuários são referência para classificar o serviço e não são objeto, nesse tratamento, de [[classificação individual, rotulagem dinâmica ou bloqueio por faixa etária]]. Safety by Design, no Princípio 2.3, descreve técnicas preventivas, inclusive colocar conteúdo atrás de [[age-gates ou avisos intersticiais]] para consentimento informado. A comparação evidencia que os textos tratam de instrumentos e âmbitos distintos. Não cabe fundi-los numa única regra, alegar que o SbD revoga a formulação local ou concluir, a partir do §3º, que toda prática de moderação é proibida. O §14 do próprio documento local ainda considera políticas de moderação.', ['Art. 48, §3º e §14, inciso III'],[a.ugc,a.moderation],[s.alerts],['Principle 2.3']);
add('Por que relacionar critérios do Art. 48 e boas práticas de Safety by Design não autoriza afirmar eficácia comprovada dessas práticas?',
'O Art. 48 local enumera funcionalidades e aspectos adicionais a considerar, remetendo detalhes aos [[Guias Práticos]]. Safety by Design apresenta seus princípios como [[voluntários]] e declara que as notas de boas práticas são ilustrações e guias, sem evidência robusta de eficácia e impacto. A síntese útil para a arguição é separar [[critério documental, recomendação de projeto e evidência de resultado]]. Uma correlação pode orientar o que investigar, mas não transforma uma lista de fatores nem um exemplo de boa prática em demonstração de redução de dano.', ['Art. 48, §§14 e 15'],[a.editorial,a.moderation,a.details],[s.voluntary],['V. Safety by Design Principles']);
add('Como o §13 do Art. 48 local dialoga com a arbitragem regulatória discutida em Games Made Elsewhere, sem provar que ela foi superada?',
'O §13 menciona informações claras e atualizadas sobre [[representantes de provedores que operem no território nacional]], com finalidades institucionais, regulatórias e de responsabilização. Games Made Elsewhere discute teoricamente a [[arbitragem regulatória]], em que diferenças de proteção e capacidade de aplicação de regras entre regiões permitem assimetrias de exploração. A relação é analítica: identificação e interlocução do prestador são uma frente institucional relevante para discutir responsabilização. O documento local não comprova implementação, fiscalização ou eliminação das assimetrias; a tese do artigo tampouco demonstra que esse dispositivo específico seja eficaz.', ['Art. 48, §13'],[a.representative],[s.chipArbitrage],['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability']);
add('Por que a lista de funcionalidades do Art. 48 deve ser discutida junto ao contexto de consumo destacado pelo creator-consumer divide?',
'O §10º inventaria interação, dados, compras, curadoria e permanência prolongada. Games Made Elsewhere argumenta que uma solução considerada segura num contexto [[WEIRD pode tornar-se danosa num contexto não-WEIRD]] e questiona a validade externa de conhecimento concentrado em certas populações. A comparação sugere que nomear uma funcionalidade não esgota a análise de sua implementação e de quem a utiliza. Isso fundamenta uma pergunta contextual sobre [[vulnerabilidades e condições de uso]], sem afirmar que o Art. 48 tenha medido diferenças entre países ou que o artigo tenha testado empiricamente cada recurso listado.', ['Art. 48, §10º'],[a.features,a.features2],[s.chipContext],['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability']);
add('Como compras, dados e retenção listados no Art. 48 se articulam no cenário de Helena, e qual é o limite dessa comparação?',
'O documento local lista [[compras on-line, compartilhamento de dados, desativação de proteções e funcionalidades de permanência prolongada]]. No cenário de Helena, o artigo imagina progressão dependente de grinding ou pagamento, um compromisso com renda futura e venda de um perfil psicológico para mensagens políticas. A síntese mostra uma possível articulação entre mecanismos: dados podem informar personalização e pressão monetária, enquanto a retenção mantém a pessoa no circuito. O limite é decisivo: Helena e Ouroboros Seed pertencem a um [[cenário especulativo]], não a um estudo de caso observado; a comparação não prova esse encadeamento em aplicativos reais nem permite inferi-lo da simples presença dos recursos.', ['Art. 48, §10º, incisos IX a XI e XX'],[a.features,a.features2],[s.chipScenario],['3 A Speculative Perspective: Helena and The Gilded Cage of Ouroboros Seed']);
add('Como a discussão de parcerias equitativas em Games Made Elsewhere pode qualificar perguntas de pesquisa sobre os critérios do Art. 48?',
'O Art. 48 local remete critérios e especificações aos [[Guias Práticos]]; ele não oferece, nesses trechos, uma descrição de pesquisa participativa com usuários. Games Made Elsewhere questiona tratar comunidades do Sul Global apenas como fontes de dados e propõe [[parcerias equitativas e cocriação de agendas e paradigmas de projeto]]. A conexão, como proposta de investigação para arguição, é perguntar quem participa da definição e avaliação de critérios e como condições locais de uso são consideradas. Não se pode inferir do silêncio do arquivo que não houve participação, nem atribuir ao artigo uma avaliação do processo de elaboração desse documento específico.', ['Art. 48, §2º e §15'],[a.guide,a.details],[s.chipPartnership],['4 Toward a Decolonial Game and Play Research']);
add('Como distinguir a observação de funcionalidades de retenção no Art. 48 da agenda de engajamento sustentável de From Understanding to Intervention?',
'O §10º inclui recursos de [[compulsividade e permanência prolongada]], como notificações, recompensas e autoplay. A agenda de intervenção propõe construir e testar interfaces que respeitem [[agência, escolha informada e motivação intrínseca]], sem exigir a eliminação de toda monetização ou engajamento. A relação não é uma equivalência entre recurso e dano: o documento local indica elementos de avaliação, enquanto a agenda pergunta como projetar e testar alternativas concretas. A comparação permite discutir qualidade e voluntariedade do engajamento, em vez de usar somente tempo de sessão como medida de sucesso.', ['Art. 48, §10º, incisos III e XX'],[a.features,a.features2],[s.agendaChoice],['3 A Call To Action: Why (and How) We Can (and Should) Go Beyond Our Current Efforts']);
add('Como notificações constantes e alertas protetivos podem produzir uma tensão de projeto ao ler Art. 48 e a agenda de intervenção?',
'O Art. 48 local cita [[notificações constantes]] entre funcionalidades que incentivam permanência prolongada. From Understanding to Intervention propõe apoio contextual, mas alerta para [[fadiga de alertas, falsos positivos e intrusão]], além de rejeitar ferramentas que enganem o usuário para impor uma escolha supostamente melhor. A conexão é que uma intervenção bem-intencionada também precisa examinar sua própria mecânica de interrupção. O propósito protetivo não é prova suficiente de boa experiência; a agenda pede pesquisa e teste, e não apresenta eficácia já estabelecida dessas ferramentas.', ['Art. 48, §10º, inciso XX'],[a.features2],[s.agendaTool],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']);
add('Por que o dever de identificar representantes no Art. 48 não deve ser confundido com a autonomia cotidiana de quem desenha a interface?',
'O §13 organiza informações de [[representação e responsabilização institucional]]. From Understanding to Intervention observa que decisões de monetização podem vir de acionistas, executivos e equipes de produto, deixando designers com [[autonomia limitada]] para rejeitar práticas manipulativas. A síntese distingue o contato e a responsabilidade do provedor das condições internas de decisão do projeto. Para investigar prevenção, é relevante perguntar quem decide, com quais metas e restrições. Nenhum dos trechos demonstra como uma empresa particular distribui esse poder; a agenda propõe pesquisa empírica para compreendê-lo.', ['Art. 48, §13'],[a.representative],[s.agendaPower],['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']);
add('Que diferença metodológica existe entre classificar fatores listados no Art. 48 e medir bem-estar na agenda de From Understanding to Intervention?',
'O documento local lista conteúdos e funcionalidades como elementos para [[atribuição da classificação indicativa]], com metodologia remetida aos Guias. A agenda de intervenção pede desenvolver e validar métodos que avaliem diretamente [[autonomia, manipulação percebida e bem-estar psicológico]] e o impacto de contramedidas. São objetos relacionados, mas distintos: registrar uma funcionalidade ou atribuir uma classificação não mede automaticamente o efeito sobre uma pessoa. A correlação ajuda a formular estudos que conectem observação do desenho, contexto e experiência, sem afirmar que os resultados psicológicos já estejam demonstrados.', ['Art. 48, §10º e §11'],[a.features,a.features2,a.method],[s.agendaValidate],['3.3 Advancing Methods and Measures for Assessing Dark Pattern Prevalence and Player Experience, Including Well-Being']);
add('Como Untranslation e Terms/Policy Out of Bounds, observados no Interact, ajudam a problematizar a clareza e a acessibilidade dos termos no Art. 48?',
'O §12 do Art. 48 local trata da indicação etária [[clara e acessível nos termos de uso]] dos fornecedores que hospedem conteúdo de terceiros. O Interact descreve casos em que termos ou políticas aparecem em [[outra língua]] mesmo com aplicativo no idioma local, ou exigem sair para uma página externa, criando barreiras de acesso à informação. A comparação distingue existir uma informação e ela ser alcançável/compreensível durante o uso. Esses casos dão exemplos empíricos para uma discussão de interface; não demonstram descumprimento desse documento local por aplicativos determinados nem substituem uma análise jurídica.', ['Art. 48, §12'],[a.terms],[s.interactTerms],['3 Results — Terms/Policy in Another Language; Terms/Policy Out of Bounds']);
add('Por que publicidade e recompensas precisam ser examinadas pela dinâmica de interação, ao correlacionar Art. 48 e os casos do Interact?',
'O Art. 48 local considera publicidade, compras e mecanismos que mantêm usuários ativos por longos períodos. O Interact descreve [[anúncios em camadas]], recompensas vinculadas a tarefas e [[recompensas bloqueadas por anúncio]]. A conexão é que não basta registrar a presença de um anúncio: importa como ele reorganiza tempo, tarefas e acesso a benefícios. Contudo, as categorias têm funções distintas: uma lista classificatória não é a taxonomia de DPs do estudo, e os casos identificados no corpus não comprovam efeitos psicológicos em cada usuário.', ['Art. 48, §7º; §10º, incisos IX e XX'],[a.ad,a.features,a.features2],[s.interactReward],['3 Results — Ads with layers; Task-based Rewards; Ad-locked Rewards']);
add('Como o protocolo de dez minutos do Interact limita uma investigação das funcionalidades de uso prolongado citadas no Art. 48?',
'O inciso XX do §10º considera funcionalidades que incentivam [[permanência prolongada]]. O Interact gravou [[os primeiros dez minutos]] de uso seguindo tarefas, sem compras efetivas, e reconhece que interações e DPs podem variar com uso estendido ou não aparecer em emulação. A síntese diferencia detectar sinais de retenção numa sessão inicial e observar suas dinâmicas ao longo do tempo. O estudo pode fornecer achados sobre o recorte examinado; não sustenta sozinho uma avaliação completa de exposição prolongada, recorrência longitudinal ou efeitos sobre o bem-estar.', ['Art. 48, §10º, inciso XX'],[a.features2],[s.interactProtocol,s.interactLimits],['2.2 Corpus Generation and Recording of Usage; 5 Limitations']);
add('Por que um achado sobre aplicativos gratuitos no Interact não esgota o escopo dos serviços avaliados no documento local do Art. 48?',
'O Art. 48 local inclui provedores audiovisuais e serviços de mensageria com interações públicas ou privadas. O Interact restringe sua análise a [[aplicativos gratuitos em alta na Google Play brasileira]], com dez minutos iniciais e uso de emulador, e assinala que desvios desse recorte podem gerar outros resultados. A comparação exige manter [[escopo documental e amostra empírica]] separados: uma pesquisa de interfaces pode informar a discussão, mas não representa automaticamente todos os serviços, versões, modelos de acesso e situações abrangidos pelo documento.', ['Art. 48, incisos I e II'],[a.scope],[s.interactLimits],['5 Limitations']);
add('Como os fatores de compulsividade do Art. 48 podem ser relacionados à definição preventiva de Radiant Patterns sem converter um checklist em diagnóstico?',
'O §10º do documento local considera mecanismos ligados à [[compulsividade, dependência e permanência prolongada]]. Operationalizing define RPs como escolhas intencionais que permitem objetivos de desenvolvimento sem prejudicar significativamente o bem-estar fundamental, evitando diminuição de [[autonomia, vínculo e competência]] e riscos previsíveis de dano psicológico. A síntese relaciona elementos observáveis de interação a perguntas sobre necessidades psicológicas. Não é uma correspondência automática: a presença de um recurso não prova frustração de necessidades, e cumprir um inventário classificatório não basta para declarar um design radiante.', ['Art. 48, §10º, incisos III e XX'],[a.features,a.features2],[s.opDefinition],['4 Revisiting and Reshaping Game Radiant Patterns']);
add('Por que o fato de o Art. 48 listar uma funcionalidade não elimina a necessidade de contexto exigida pelo template de Operationalizing?',
'O Art. 48 lista [[compras, comunicação, dados e curadoria]], entre outras funcionalidades. O template de Operationalizing pede descrever [[problema, contexto e solução]], incluindo cenários e estilos em que o padrão pode ser usado e como ele afeta cada necessidade psicológica. A conexão mostra a diferença entre inventariar uma capacidade e analisar uma implementação situada. Uma funcionalidade de compra, por exemplo, não especifica sozinha como a interface a apresenta; a evidência das duas fontes não autoriza classificar toda ocorrência como radiante ou enganosa.', ['Art. 48, §10º'],[a.features,a.features2],[s.opContext],['5 Crafting Radiance: A Guide to Propose Radiant Patterns']);
add('Como o tratamento de interações de risco no Art. 48 se aproxima da prevenção de danos previsíveis em Operationalizing, e onde os escopos divergem?',
'O §10º do Art. 48 local inclui [[desafios ou interações que estimulem risco, autolesão ou violência]] e mecanismos de compulsividade. Operationalizing substitui o ideal de evitar toda experiência negativa por [[minimizar riscos previsíveis de dano psicológico]] e evitar padrões conhecidos de frustração de necessidades. Há um ponto preventivo comum, mas não identidade de escopo: o documento local organiza elementos para classificação e abrange tipos amplos de conteúdo/interação; o refinamento de RPs oferece critérios para decisões de design ligadas à teoria de autodeterminação. Não se deve equiparar desafio de jogo a dano só por produzir emoção negativa.', ['Art. 48, §10º, incisos II e III'],[a.features],[s.opPrevention],['4 Revisiting and Reshaping Game Radiant Patterns']);
add('Como a avaliação de controles e moderação do Art. 48 pode ser enriquecida pelo cuidado de Operationalizing com implementações que produzem o efeito oposto?',
'O §14 do documento local considera [[controles acessíveis e políticas de moderação]]. Operationalizing recomenda documentar situações em que aplicar um padrão de modo irregular pode [[prejudicar o jogador em vez de ajudá-lo]], apresentando exemplos positivos e negativos de implementação. A comparação orienta uma pergunta de arguição: além de existir, como uma proteção funciona e em quais condições pode falhar? Isso é uma proposta de análise derivada dos dois trechos, não um resultado empírico de que os controles citados no Art. 48 falharam ou de que um RP validou sua eficácia.', ['Art. 48, §14, incisos II e III'],[a.moderation],[s.opRisk],['5 Crafting Radiance: A Guide to Propose Radiant Patterns']);
add('Como Open Gate no framework HCI oferece um contraponto analítico às funcionalidades de permanência prolongada do Art. 48?',
'O inciso XX do §10º destaca funcionalidades que incentivam a [[manutenção do usuário ativo por períodos prolongados]]. Em Beyond Dark Patterns, Open Gate é descrito em níveis que incluem [[salvamento automático]], [[parada intencional]] e feedback visual de realização. A relação permite discutir se a arquitetura oferece condições de sair e voltar sem que a permanência seja imposta pela perda de progresso. O texto do HCI apresenta uma estrutura de padrões; a comparação não demonstra que ela reduziu compulsividade em estudo longitudinal nem que todo recurso de retenção viole a classificação descrita no documento local.', ['Art. 48, §10º, inciso XX'],[a.features2],[s.hciOpen],['4.2 Refined RPs Framework — progressive scaling']);
add('Por que níveis L1–L3 de Radiant Patterns não podem ser tratados como se fossem faixas etárias de classificação do Art. 48?',
'O Art. 48 local remete a [[critérios e metodologia de classificação indicativa]] dos Guias. O HCI esclarece que os [[níveis universais L1–L3 são uma base metodológica]], não uma alegação de experiência universal, e admite variantes que preservam a identidade conceitual em contextos distintos. São instrumentos com objetos diferentes: níveis estruturam a análise de padrões e necessidades; faixas etárias pertencem ao processo classificatório mencionado no documento. Não existe nos trechos uma tabela de conversão entre eles nem evidência para inventar essa equivalência.', ['Art. 48, §2º e §11'],[a.guide,a.method],[s.hciContext],['6 Discussion — universal levels and contextual variants']);
add('Como a separação entre objetivos do desenvolvedor e resultados do jogador no HCI ajuda a discutir as funcionalidades de retenção do Art. 48?',
'O Art. 48 local cita recursos que incentivam [[permanência prolongada]]. O template refinado do HCI exige [[separar objetivos técnicos de desenvolvimento e problemas/resultados do jogador]], além de explicitar atores, contexto, invariantes, variantes e necessidades. Essa distinção permite perguntar se uma meta de retenção corresponde ao que a pessoa deseja ou se mascara frustração de necessidades. A correlação é uma ferramenta de raciocínio para a arguição; não prova uma divergência em um aplicativo específico nem afirma que o documento local adota esse mesmo template.', ['Art. 48, §10º, inciso XX'],[a.features2],[s.hciRules],['4.2 An Updated Radiant Pattern Framework']);
add('Por que critérios de conteúdo/interação do Art. 48 e padrões de interface do HCI precisam ser discutidos com dimensões institucionais mais amplas?',
'O Art. 48 local inclui [[conteúdos discriminatórios, interações que estimulam violência e informações para responsabilização do provedor]]. O HCI reconhece que um léxico de padrões é uma ferramenta de design de interação e não resolve todos os problemas éticos: [[assédio, toxicidade on-line e bem-estar de trabalhadores]] também demandam intervenções culturais e regulatórias fora desse escopo. A síntese distingue a utilidade de critérios e padrões de uma pretensão de solução completa. Nenhum dos textos, isoladamente, demonstra que instrumentos de interface ou classificação eliminem problemas sistêmicos.', ['Art. 48, §10º, incisos I e II; §13'],[a.features,a.representative],[s.hciLimit],['6 Discussion — limits of interaction design']);

if(cards.length!==50)throw Error(`Expected 50, got ${cards.length}`);
fs.mkdirSync(out,{recursive:true});
fs.writeFileSync(path.join(out,`${docs[primary].articleId}.json`),JSON.stringify(cards,null,2)+'\n','utf8');
